mapper.select:
SELECT COUNT(*)
FROM reservation r
INNER JOIN service_item s ON s.id = r.service_id
WHERE r.status != 'CANCELLED'
  AND r.reservation_start < #{reservationEnd}
  AND DATE_ADD(r.reservation_start, INTERVAL s.duration_minutes MINUTE) > #{reservationStart}

  AND r.id != #{excludeId}

mapper.update:
UPDATE reservation
SET service_id = #{serviceId},
    reservation_start = #{reservationStart},
    request_memo = #{requestMemo}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'REQUESTED'

UPDATE reservation
SET status = 'CANCELLED'
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'REQUESTED'
